function visibleAlerts(){const alerts=buildFarmAlerts().filter(alert=>viewAllowedBySystem(alert.view)),role=sessionRole(),workerId=currentWorkerId();if(canManageStaff()||role==='SUPERVISOR'||role==='VIEWER')return alerts;if(role==='VET')return alerts.filter(alert=>alert.assigneeId===workerId||['Health','Breeding'].includes(alert.category));return alerts.filter(alert=>alert.assigneeId===workerId);}
