function salePaid(record){return Number(record.amountPaid||0)+(state.salePayments||[]).filter(row=>row.saleId===record.id).reduce((sum,row)=>sum+Number(row.amount||0),0);}
function salePaymentStatus(record){const paid=salePaid(record),total=Number(record.total||0);return paid>=total-.005?'PAID':paid>0?'PART PAID':'CREDIT';}
function saleLines(record){return Array.isArray(record?.items)&&record.items.length?record.items:[{id:`${record?.id||'sale'}-line`,lotId:record?.lotId,lotCode:record?.lotCode,item:record?.item,quantity:Number(record?.quantity||0),unit:record?.unit,unitPrice:Number(record?.unitPrice||0),total:Number(record?.total||0),sourceType:record?.sourceType,sourceId:record?.sourceId,sourceLabel:record?.sourceLabel}];}
