function lotSold(lotId){return Math.max(0,(state.sales||[]).filter(row=>row.status!=='VOID').reduce((sum,row)=>sum+saleLines(row).filter(line=>line.lotId===lotId).reduce((n,line)=>n+Number(line.quantity||0),0),0)-returnedToStock(lotId));}
