function lotBalance(lot){return Math.max(0,Number(lot.openingQuantity||0)-lotSold(lot.id)-lotReserved(lot.id));}
function liveLotStatus(lot){if(lot.status!=='WITHHELD')return lot.status||'AVAILABLE';return lot.releaseDate&&lot.releaseDate<todayKey()?'AVAILABLE':'WITHHELD';}
function reservableLotForOrder(order){const quantity=Number(order.quantity||0),preferred=(state.productionLots||[]).find(row=>row.id===order.lotId),works=lot=>lot&&liveLotStatus(lot)==='AVAILABLE'&&lotBalance(lot)+.005>=quantity;if(works(preferred))return preferred;return (state.productionLots||[]).filter(lot=>works(lot)&&String(lot.product).trim().toLowerCase()===String(order.item).trim().toLowerCase()&&String(lot.unit).trim().toLowerCase()===String(order.unit).trim().toLowerCase()).sort((a,b)=>String(a.expiryDate||a.packagedDate||'9999').localeCompare(String(b.expiryDate||b.packagedDate||'9999')))[0]||null;}
function showOrderActionStatus(button,message,kind='error'){const card=button.closest('.customer-order'),actions=card?.querySelector('.order-actions');if(!card||!actions)return;card.querySelector('.order-action-status')?.remove();actions.insertAdjacentHTML('beforebegin',`<p class="order-action-status ${kind}">${escapeHtml(message)}</p>`);}
