  const revenue=state.sales.reduce((sum,record)=>sum+Number(record.total||0),0),outstanding=state.sales.reduce((sum,record)=>sum+Math.max(0,Number(record.total||0)-salePaid(record)),0),sellable=state.productionLots.filter(row=>liveLotStatus(row)==='AVAILABLE').reduce((sum,row)=>sum+lotBalance(row),0),held=state.productionLots.filter(row=>liveLotStatus(row)==='WITHHELD').reduce((sum,row)=>sum+lotBalance(row),0),rejected=(state.production||[]).reduce((sum,row)=>sum+Number(row.rejected||0),0),expired=state.productionLots.filter(row=>row.expiryDate&&row.expiryDate<todayKey()).reduce((sum,row)=>sum+lotBalance(row)*Number(row.packSize||1),0);
