  const activeOrders=state.customerOrders.filter(row=>['CONFIRMED','READY','DISPATCHED'].includes(row.status)),orderPipeline=activeOrders.reduce((sum,row)=>sum+Number(row.total||0),0),reserved=activeOrders.reduce((sum,row)=>sum+Number(row.quantity||0),0),due=activeOrders.filter(row=>row.fulfilment==='DELIVERY'&&row.status!=='DELIVERED').length;$('#openOrderCount').textContent=activeOrders.length;$('#reservedStock').textContent=reserved.toLocaleString();$('#orderPipeline').textContent=`GHS ${orderPipeline.toLocaleString()}`;$('#deliveryDue').textContent=due;
