function dutyDueToday(schedule,today){
  if(schedule.status==='INACTIVE'||schedule.startDate>today)return false;
  const start=new Date(`${schedule.startDate}T12:00:00`),date=new Date(`${today}T12:00:00`);
  if(schedule.frequency==='ONE_TIME')return schedule.startDate<=today;
  if(schedule.frequency==='WEEKLY')return start.getDay()===date.getDay();
  if(schedule.frequency==='MONTHLY')return start.getDate()===date.getDate();
  return true;
}
