  for(const record of state.healthRecords||[])for(const [product,key] of types)if(record.date<=onDate&&record[key]&&record[key]>=onDate)rows.push({record,product,until:record[key],daysLeft:Math.max(0,Math.ceil((new Date(`${record[key]}T12:00:00`)-new Date(`${onDate}T12:00:00`))/86400000))});
