function queueWorkspaceSnapshot(createdAt=new Date().toISOString()){
  const farmId=state.activeFarmId||state.farm?.id;
  if(!farmId)return null;
  const workspace=farmWorkspaceSnapshot(farmId);state.farmWorkspaces={...(state.farmWorkspaces||{}),[farmId]:workspace};state.offlineQueue=state.offlineQueue.filter(command=>!(command.status==='PENDING_SYNC'&&command.entityType==='FarmWorkspace'&&command.entityId===workspace.id));
  const command={id:newId(),organizationId:currentSession?.user?.organizationId||'local-admin-workspace',entityType:'FarmWorkspace',entityId:workspace.id,baseVersion:0,payload:{record:workspace,operations:[]},localCreatedAt:createdAt,status:'PENDING_SYNC'};state.offlineQueue.push(command);return command;
}
let workspaceSnapshotScheduled=false,workspaceSnapshotCreatedAt='';
function scheduleWorkspaceSnapshot(createdAt=new Date().toISOString()){
  workspaceSnapshotCreatedAt=createdAt;
  if(workspaceSnapshotScheduled)return;
  workspaceSnapshotScheduled=true;
  queueMicrotask(()=>{
    workspaceSnapshotScheduled=false;
    queueWorkspaceSnapshot(workspaceSnapshotCreatedAt);
    saveState(state,stateNamespace()).catch(()=>{});
  });
}
function queueCreation(entityType,entity){
  const createdAt=new Date().toISOString();
  if(entity&&entityType!=='Farm'&&entityType!=='FarmWorkspace'&&!entity.farmId)entity.farmId=state.activeFarmId||state.farm?.id;
  const command={id:newId(),organizationId:currentSession?.user?.organizationId||'local-admin-workspace',entityType,entityId:entity.id,baseVersion:0,payload:{record:entity,operations:[]},localCreatedAt:createdAt,status:'PENDING_SYNC'};state.offlineQueue.push(command);
  if(!['Farm','FarmWorkspace','CrossFarmTransfer','TeamMember','FarmProfile'].includes(entityType))scheduleWorkspaceSnapshot(createdAt);
  state.audit.push({id:newId(),action:`${entityType.toUpperCase()}_CREATED`,entityId:entity.id,at:createdAt});
  scheduleCloudSync();
  return command;
}
function requireSecondTap(button){
  if(button.dataset.confirmed==='true') return true;
  button.dataset.confirmed='true'; button.classList.add('confirming'); button.textContent='Tap to confirm';
  setTimeout(()=>{if(button.isConnected){button.dataset.confirmed='false';button.classList.remove('confirming');button.textContent='Reverse';}},4000);
  return false;
}
document.addEventListener('click',async event=>{
  const populationButton=event.target.closest('[data-reverse-population]');
  if(populationButton){
    if(!requireSecondTap(populationButton)) return;
    const original=state.populationEvents.find(record=>record.id===populationButton.dataset.reversePopulation);
    if(!original||state.populationEvents.some(record=>record.reversesEventId===original.id)){renderAll();return;}
    const reversal={id:newId(),flockId:original.flockId,type:'REVERSAL',quantityDelta:-Number(original.quantityDelta),eventDate:new Date().toISOString(),reversesEventId:original.id,reason:'Admin correction'};
    const resulting=population(original.flockId)+reversal.quantityDelta;
    if(resulting<0){formError('#populationLedgerStatus','This reversal would make the flock population negative and was blocked.');return;}
    state.populationEvents.push(reversal);queueCreation('FlockPopulationReversal',reversal);await saveState(state,stateNamespace());$('#populationLedgerStatus').textContent='Population event reversed with a linked compensating entry.';renderAll();return;
  }
  const movementButton=event.target.closest('[data-reverse-movement]');
  if(movementButton){
    if(!requireSecondTap(movementButton)) return;
    const original=state.stockMovements.find(record=>record.id===movementButton.dataset.reverseMovement),item=original&&state.inventoryItems.find(record=>record.id===original.inventoryItemId);
    if(!original||!item||state.stockMovements.some(record=>record.reversesMovementId===original.id)){renderAll();return;}
    const originalIncoming=Boolean(original.toLocationId&&!original.fromLocationId)||Number(original.quantityDelta)>0&&!original.fromLocationId,quantity=Math.abs(Number(original.quantityDelta));
    if(originalIncoming&&quantity>stock(item)){formError('#movementLedgerStatus',`Cannot reverse this receipt because only ${stock(item).toLocaleString()} ${item.unit} remains.`);return;}
    const reversal={id:newId(),inventoryItemId:item.id,type:'REVERSAL',quantityDelta:-Number(original.quantityDelta),occurredAt:new Date().toISOString(),reference:`Reversal of ${original.reference||original.type}`,reversesMovementId:original.id,...(originalIncoming?{fromLocationId:item.locationId}:{toLocationId:item.locationId})};
    state.stockMovements.push(reversal);queueCreation('StockMovementReversal',reversal);await saveState(state,stateNamespace());$('#movementLedgerStatus').textContent='Stock movement reversed with a linked compensating entry.';renderAll();
  }
});
