const animalEventHelp={TRANSFER:'Enter the new location. The previous location remains in history.',WEIGHT:'Enter the latest weight per animal.',STATUS:'Choose the new health or lifecycle status.',QUANTITY_IN:'Add newly acquired or born animals to an existing group.',QUANTITY_OUT:'Remove animals transferred out of this group.',SALE:'Enter the number sold and optional total value.',DEATH:'Enter the mortality quantity and cause in the reference.'};
