$('#animalEventType').addEventListener('change',event=>{$('#animalEventHelp').textContent=animalEventHelp[event.target.value];});
$('#animalEventForm').addEventListener('submit',async event=>{
  event.preventDefault();const animal=state.animals.find(row=>row.id===$('#animalEventAnimal').value),type=$('#animalEventType').value,date=$('#animalEventDate').value,quantity=Number($('#animalEventQuantity').value||1),location=$('#animalEventLocation').value.trim(),weight=Number($('#animalEventWeight').value||0),status=$('#animalEventStatus').value;
  if(!animal||!date){formError('#animalEventStatusLine','Choose an animal and activity date.');return;}if(!Number.isInteger(quantity)||quantity<1){formError('#animalEventStatusLine','Quantity must be a whole number of at least 1.');return;}
  if(type==='TRANSFER'&&!location){formError('#animalEventStatusLine','Enter the new location for this transfer.');return;}if(type==='WEIGHT'&&!(weight>0)){formError('#animalEventStatusLine','Enter the new weight per animal.');return;}
  const transferLocation=type==='TRANSFER'?resolveLocation(location):null;if(transferLocation){const capacityMessage=capacityError(transferLocation,Number(animal.quantity||1),0);if(capacityMessage){formError('#animalEventStatusLine',capacityMessage);return;}}
  if(type==='QUANTITY_IN'&&animal.recordType!=='GROUP'){formError('#animalEventStatusLine','Only grouped livestock can receive a quantity addition. Register a separate individual animal instead.');return;}
  if(['QUANTITY_OUT','SALE','DEATH'].includes(type)&&quantity>Number(animal.quantity||1)){formError('#animalEventStatusLine',`Only ${Number(animal.quantity||1)} head are currently available.`);return;}
  const record={id:newId(),animalId:animal.id,animalLabel:animal.id,type,date,quantity,location,weight,status,value:Number($('#animalEventValue').value||0),reference:$('#animalEventReference').value.trim(),notes:$('#animalEventNotes').value.trim(),previousQuantity:Number(animal.quantity||1),previousLocation:animal.location,previousStatus:animal.status,createdAt:new Date().toISOString()};
  if(type==='TRANSFER'){animal.location=transferLocation?.name||location;animal.locationId=transferLocation?.id||animal.locationId;}if(type==='WEIGHT')animal.weight=weight;if(type==='STATUS')animal.status=status;if(type==='QUANTITY_IN')animal.quantity=Number(animal.quantity||1)+quantity;
  if(['QUANTITY_OUT','SALE','DEATH'].includes(type)){animal.quantity=Number(animal.quantity||1)-quantity;if(animal.quantity===0)animal.status=type==='SALE'?'SOLD':type==='DEATH'?'DECEASED':'TRANSFERRED';}
  state.animalEvents.push(record);queueCreation('AnimalActivity',record);queueCreation('Animal',{...animal});await saveState(state,stateNamespace());event.target.reset();event.target.hidden=true;$('#animalEventHelp').textContent=animalEventHelp.TRANSFER;renderAll();
});

function refreshBreedingAnimals(){
  const females=state.animals.filter(animal=>String(animal.sex).toLowerCase()==='female'&&Number(animal.quantity||1)===1&&!['SOLD','DECEASED'].includes(animal.status));
  $('#breedingAnimal').innerHTML=females.map(animal=>`<option value="${escapeHtml(animal.id)}">${escapeHtml(animal.id)} — ${escapeHtml(animal.species)}</option>`).join('');
}
