$('#receiptForm').addEventListener('submit',async event=>{event.preventDefault();const order=state.purchases.find(row=>row.id===$('#receiptPurchaseId').value),received=Number($('#receiptQuantity').value),accepted=Number($('#receiptAccepted').value),damaged=Number($('#receiptDamaged').value||0),rejected=Number($('#receiptRejected').value||0),freight=Number($('#receiptFreight').value||0),otherCost=Number($('#receiptOtherCost').value||0),item=state.inventoryItems.find(row=>row.id===$('#receiptInventory').value);if(!order||received<0||accepted<0||damaged<0||rejected<0||accepted+damaged+rejected!==received){formError('#receiptStatus','Accepted, damaged and rejected quantities must exactly equal the received quantity.');return;}const receipt={id:newId(),purchaseId:order.id,supplierId:order.supplierId,supplierName:order.supplierName,received,accepted,damaged,rejected,freight,otherCost,inspectionNotes:$('#receiptNotes').value.trim(),receivedAt:new Date().toISOString(),receivedBy:currentSession?.user?.name||'Farm manager',status:damaged||rejected?'DISCREPANCY':'ACCEPTED'};state.goodsReceipts.push(receipt);order.receivedQuantity=Number(order.receivedQuantity||0)+received;order.acceptedQuantity=Number(order.acceptedQuantity||0)+accepted;order.status=order.receivedQuantity>=Number(order.quantity)?'RECEIVED':'PART_RECEIVED';order.receivedAt=receipt.receivedAt;order.landedCostTotal=Number(order.quantity)*Number(order.unitCost)+freight+otherCost;order.unitLandedCost=accepted?order.landedCostTotal/accepted:Number(order.unitCost);if(item&&accepted>0){const movement={id:newId(),inventoryItemId:item.id,toLocationId:item.locationId,quantityDelta:accepted,type:'PURCHASE_RECEIPT',occurredAt:receipt.receivedAt,reference:`${order.poNumber||order.item} · inspected receipt`,goodsReceiptId:receipt.id,unitCost:order.unitLandedCost};state.stockMovements.push(movement);queueCreation('StockMovement',movement);}queueCreation('GoodsReceipt',receipt);queueCreation('Purchase',{...order});await saveState(state,stateNamespace());event.target.reset();event.target.hidden=true;renderAll();});

