  const window=statementWindow(input.period),within=date=>String(date||'').slice(0,10)>=window.from&&String(date||'').slice(0,10)<=window.to,money=value=>`GHS ${Number(value||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}`,sales=(state.sales||[]).filter(row=>within(row.date)),expenses=(state.expenses||[]).filter(row=>within(row.date)),cashRows=financeCashbook().filter(row=>within(row.date)),revenue=sales.reduce((sum,row)=>sum+Number(row.total||0),0),costs=expenses.reduce((sum,row)=>sum+Number(row.amount||0),0),net=revenue-costs,margin=revenue?net/revenue*100:0,cashIn=cashRows.filter(row=>row.type==='IN').reduce((sum,row)=>sum+row.amount,0),cashOut=cashRows.filter(row=>row.type==='OUT').reduce((sum,row)=>sum+row.amount,0),cashNet=cashIn-cashOut,receivables=(state.sales||[]).reduce((sum,row)=>sum+Math.max(0,Number(row.total||0)-salePaid(row)),0),payables=(state.purchases||[]).filter(row=>row.status!=='CANCELLED').reduce((sum,row)=>sum+Math.max(0,purchaseTotal(row)-purchasePaid(row)),0),inventoryValue=(state.inventoryItems||[]).reduce((sum,item)=>sum+Math.max(0,stock(item))*Number(item.costPerKg||item.unitCost||item.averageCost||0),0),birds=(state.flocks||[]).filter(row=>row.status==='ACTIVE').reduce((sum,row)=>sum+Math.max(0,population(row.id)),0),livestock=(state.animals||[]).filter(row=>!['SOLD','DECEASED','TRANSFERRED'].includes(row.status)).reduce((sum,row)=>sum+Number(row.quantity||1),0),months=new Map();
