function refreshMovementItems(){
  const select=$('#movementItem');
  select.innerHTML=state.inventoryItems.map(item=>`<option value="${escapeHtml(item.id)}">${escapeHtml(item.name)}</option>`).join('');
  const item=state.inventoryItems.find(record=>record.id===select.value)||state.inventoryItems[0];
  $('#movementBalance').textContent=item?`Available: ${stock(item).toLocaleString()} ${item.unit} at ${item.locationName||item.locationId}.`:'Add a stock item before recording movements.';
}
