      const event={...recordMortality(target.id,input.mortality,state.populationEvents),eventDate:`${date}T12:00:00.000Z`,quickEntry:true};state.populationEvents.push(event);queueCreation('FlockPopulationEvent',event);refs.populationEventId=event.id;
