      const available=Number(target.record?.quantity||1);if(input.mortality>available)throw new Error(`Losses cannot exceed the current record quantity of ${available.toLocaleString()}.`);const activity={id:newId(),animalId:target.id,animalLabel:target.id,type:'MORTALITY',date,quantity:-input.mortality,reference:'Quick Farm Entry',notes:input.notes,createdAt};state.animalEvents.push(activity);target.record.quantity=Math.max(0,available-input.mortality);if(target.record.quantity===0)target.record.status='DECEASED';queueCreation('AnimalActivity',activity);queueCreation('Animal',{...target.record});refs.animalActivityId=activity.id;
