$('#restoreFile').addEventListener('change',async event=>{
  const file=event.target.files?.[0];pendingRestore=null;$('#restoreReview').hidden=true;
  if(!file)return;
  try{
    const parsed=JSON.parse(await file.text()),candidate=parsed?.state;
    const requiredArrays=['flocks','animals','populationEvents','inventoryItems','stockMovements','production','dailyRecords','offlineQueue','audit'];
    if(parsed?.app!=='Farm Manager'||![1,2].includes(parsed?.schemaVersion)||!candidate||requiredArrays.some(key=>!Array.isArray(candidate[key])))throw new Error('INVALID_BACKUP');
    pendingRestore=parsed;$('#restoreReview').hidden=false;$('#restoreTitle').textContent='Valid Farm Manager backup';$('#restoreDetails').textContent=`Created ${new Date(parsed.exportedAt).toLocaleString()} · ${candidate.flocks.length} flocks · ${candidate.animals.length} animals · ${candidate.offlineQueue.length} queued changes.`;$('#backupStatus').textContent='Review the backup details before restoring.';$('#confirmRestore').dataset.confirmed='false';$('#confirmRestore').textContent='Tap to restore';
  }catch{$('#backupStatus').textContent='This file is not a valid Farm Manager backup.';event.target.value='';}
});

$('#confirmRestore').addEventListener('click',async event=>{
  if(!pendingRestore)return;
  if(event.target.dataset.confirmed!=='true'){event.target.dataset.confirmed='true';event.target.textContent='Tap again to replace device data';return;}
  const base=structuredClone(stateSeedForSession()),restored=pendingRestore.state;state={...base,...restored};for(const key of cloudCollections)if(!Array.isArray(state[key]))state[key]=structuredClone(base[key]||[]);state.farms=Array.isArray(restored.farms)&&restored.farms.length?restored.farms:restored.farm?[restored.farm]:base.farms;state.farm=restored.farm||state.farms[0]||base.farm;state.activeFarmId=state.farms.some(farm=>farm.id===restored.activeFarmId)?restored.activeFarmId:state.farm?.id;state.farmWorkspaces=restored.farmWorkspaces&&typeof restored.farmWorkspaces==='object'?restored.farmWorkspaces:{};state.crossFarmTransfers=Array.isArray(restored.crossFarmTransfers)?restored.crossFarmTransfers:[];ensureFarmWorkspaces();state.audit.push({id:newId(),action:'DEVICE_BACKUP_RESTORED',at:new Date().toISOString(),sourceDeviceId:pendingRestore.deviceId,schemaVersion:pendingRestore.schemaVersion});await saveState(state,stateNamespace());pendingRestore=null;$('#restoreReview').hidden=true;$('#restoreFile').value='';renderAll();$('#backupStatus').textContent='Backup restored successfully on this device.';
});

